      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-16 left-0 w-full bg-slate-200 border-b border-slate-300 shadow-xl p-4 flex flex-col space-y-4 animate-in slide-in-from-top-5">
